pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;

    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(uint256 warpTs, address player) public {
        vm.assume(player != address(0));
        vm.assume(player != address(this));

        warpTs = bound(warpTs, 1, type(uint64).max);

        uint256 ticket = 10;
        vm.deal(player, ticket);

        vm.warp(uint64(warpTs));

        bool ok;
        vm.prank(player);
        try c.play{value: ticket}() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty)));

        if (random % 2 == 0) {
            assertTrue(c.pot() == 0);
        } else {
            assertTrue(true);
        }
    }
}
